r=Path.cwd();o=r/'.work/workload-native-20261116';s=o/'source'
for name in subprocess.check_output(['git','ls-files'],text=True).splitlines():
 if name.startswith(('docs/','.github/')):continue
 p=s/name;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(r/name,p)
p=s/'src/main.zig';original=p.read_text();text=original
helper='''
extern "kernel32" fn QueryPerformanceCounter(*i64) callconv(.winapi) c_int;
extern "kernel32" fn QueryPerformanceFrequency(*i64) callconv(.winapi) c_int;
var measure_calls: [4]u64 = @splat(0);
var measure_ticks: [4]i64 = @splat(0);
var measure_bytes: u64 = 0;
var measure_start: i64 = 0;
var measure_cpu: forth.CpuTimes = .{ .user = 0, .system = 0 };
fn measureClock() i64 {
    var ticks: i64 = 0;
    if (QueryPerformanceCounter(&ticks) == 0) @panic("QPC failed");
    return ticks;
}
'''
text=text.replace('const forth = @import("forth.zig");','const forth = @import("forth.zig");\n'+helper)
rows=[('fileOpen','context: ?*anyopaque, name: []const u8, access: forth.FileAccess, create: bool','forth.FileResult','context, name, access, create'),('fileClose','context: ?*anyopaque, fileid: forth.Cell','forth.Cell','context, fileid'),('fileReadLine','context: ?*anyopaque, fileid: forth.Cell, buffer: []u8','forth.LineResult','context, fileid, buffer'),('filePosition','context: ?*anyopaque, fileid: forth.Cell','forth.FileResult','context, fileid')]
for i,(name,args,result,passed) in enumerate(rows):
 needle='fn '+name+'(';assert text.count(needle)==1
 text=text.replace(needle,'fn unmeasured_'+name+'(',1)
 wrapper=f'''\nfn {name}({args}) {result} {{
    const start = measureClock();
    const result = unmeasured_{name}({passed});
    measure_ticks[{i}] += measureClock() - start;
    measure_calls[{i}] += 1;
'''+('    measure_bytes += result.length;\n' if name=='fileReadLine' else '')+'    return result;\n}\n'
 text+=wrapper
needle='        if (std.mem.eql(u8, option, "-e") or std.mem.eql(u8, option, "--evaluate")) {'
assert text.count(needle)==1
opts='''        if (std.mem.eql(u8, option, "--measure-reset")) {
            measure_calls = @splat(0); measure_ticks = @splat(0); measure_bytes = 0;
            measure_cpu = processCpuTimes(null) catch @panic("CPU clock failed");
            measure_start = measureClock();
            continue;
        }
        if (std.mem.eql(u8, option, "--measure-report")) {
            const elapsed = measureClock() - measure_start;
            const cpu = processCpuTimes(null) catch @panic("CPU clock failed");
            var frequency: i64 = 0;
            if (QueryPerformanceFrequency(&frequency) == 0) @panic("QPF failed");
            std.debug.print("MEASURE {d} {d} {d} {d} {d} {d} {d} {d} {d} {d} {d} {d}\\n", .{frequency, elapsed, cpu.user - measure_cpu.user + cpu.system - measure_cpu.system, measure_bytes, measure_calls[0], measure_calls[1], measure_calls[2], measure_calls[3], measure_ticks[0], measure_ticks[1], measure_ticks[2], measure_ticks[3]});
            continue;
        }
'''
text=text.replace(needle,opts+needle);p.write_text(text)
(o/'instrumentation.patch').write_text(''.join(difflib.unified_diff(original.splitlines(True),text.splitlines(True),fromfile='src/main.zig',tofile='measurement/src/main.zig')))
cmd=['zig','build','-Doptimize=fast','-Dcpu=baseline','-Dstrip=true','--prefix',str(o),'--summary','all']
with (o/'build.log').open('wb') as f: result=subprocess.run(cmd,cwd=s,stdout=f,stderr=subprocess.STDOUT)
(o/'build.json').write_text(json.dumps({'command':cmd,'exit':result.returncode},indent=2));assert result.returncode==0

